/* ── W-9 status badges ── */
.badge-w9-collected { background: oklch(58% 0.18 145 / 0.12); color: oklch(65% 0.14 145); border: 1px solid oklch(58% 0.18 145 / 0.3); }
.badge-w9-missing   { background: oklch(55% 0.22 27  / 0.12); color: oklch(65% 0.18 27);  border: 1px solid oklch(55% 0.22 27  / 0.3); }

/* ── Artist pay status badges ── */
.badge-pay-pending  { background: oklch(70% 0.16 72  / 0.12); color: oklch(75% 0.14 72);  border: 1px solid oklch(70% 0.16 72  / 0.3); }
.badge-pay-paid     { background: oklch(58% 0.18 145 / 0.12); color: oklch(65% 0.14 145); border: 1px solid oklch(58% 0.18 145 / 0.3); }
.badge-pay-held     { background: oklch(55% 0.22 27  / 0.12); color: oklch(65% 0.18 27);  border: 1px solid oklch(55% 0.22 27  / 0.3); }
.badge-pay-disputed { background: oklch(62% 0.24 292 / 0.12); color: oklch(72% 0.18 292); border: 1px solid oklch(62% 0.24 292 / 0.3); }

/* ── Threshold met badge ── */
.badge-threshold-met  { background: var(--color-threshold-bg); color: var(--color-threshold-text); border: 1px solid var(--color-threshold-border); }
.badge-threshold-miss { background: oklch(55% 0.02 264 / 0.12); color: oklch(65% 0.02 264); border: 1px solid oklch(55% 0.02 264 / 0.3); }

/* ── Locked form badge ── */
.badge-form-locked { background: var(--color-locked-bg); color: var(--color-locked-text); border: 1px solid var(--color-locked-border); }

/* ── Security callout block ── */
.security-callout {
  background: var(--color-security-bg);
  border: 1px solid var(--color-security-border);
  border-radius: var(--radius);
  padding: 0.75rem 1rem;
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
}
.security-callout-text {
  color: var(--color-security-text);
  font-size: 0.8125rem;
  line-height: 1.5;
}

/* ── Lock warning block ── */
.lock-warning {
  background: var(--color-lock-warning-bg);
  border: 1px solid var(--color-lock-warning-border);
  border-radius: var(--radius);
  padding: 0.75rem 1rem;
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
}
.lock-warning-text {
  color: var(--color-lock-warning-text);
  font-size: 0.8125rem;
  line-height: 1.5;
}

/* ── Payroll stats row ── */
.payroll-stats-row {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 1.5rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
}
.payroll-stat-label {
  font-size: 0.6875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: oklch(50% 0.04 264);
}
.payroll-stat-value {
  font-size: 1.25rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

/* ── Payroll timeline ── */
.payroll-timeline {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 1.25rem 1.5rem;
}
.payroll-timeline-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
  position: relative;
}
.payroll-timeline-dot {
  width: 0.625rem;
  height: 0.625rem;
  border-radius: 50%;
  position: relative;
  z-index: 1;
}
.payroll-timeline-dot-completed { background: var(--color-payroll-timeline-completed); }
.payroll-timeline-dot-current   { background: var(--color-payroll-timeline-current); box-shadow: 0 0 0 3px oklch(62% 0.24 292 / 0.2); }
.payroll-timeline-dot-pending   { background: var(--color-payroll-timeline-pending); }
.payroll-timeline-connector {
  position: absolute;
  top: 0.3125rem;
  left: calc(50% + 0.3125rem);
  right: calc(-50% + 0.3125rem);
  height: 2px;
}
.payroll-timeline-connector-done   { background: var(--color-payroll-timeline-completed); }
.payroll-timeline-connector-pending { background: var(--color-payroll-timeline-pending); }
.payroll-timeline-step-label {
  margin-top: 0.375rem;
  font-size: 0.6875rem;
  font-weight: 500;
  text-align: center;
  color: oklch(50% 0.04 264);
}
.payroll-timeline-step-label-current { color: oklch(72% 0.18 292); }
.payroll-timeline-step-ts {
  font-size: 0.625rem;
  text-align: center;
  color: oklch(45% 0.02 264);
  margin-top: 0.125rem;
  font-variant-numeric: tabular-nums;
}
