        </div>
      ) : (
        <Input name="tin_plaintext" type="password" placeholder="Enter TIN" required
               autoComplete="off" className="flex-1 font-mono" />
      )}
    </div>
    {tinEditMode && (
      <Input name="tin_plaintext" type="password" placeholder="Enter new TIN"
             autoComplete="off" className="mt-1 font-mono" />
    )}
    <p className="text-xs text-muted-foreground">
      TIN is encrypted immediately. Only the last 4 digits are stored in plain text for reference.
    </p>
  </div>

  {/* Address */}
