    <Label>Mailing address *</Label>
    <Input name="address_street" placeholder="Street address" required />
    <div className="grid grid-cols-2 gap-2">
      <Input name="address_city" placeholder="City" required />
      <Input name="address_state" placeholder="State / Province" />
    </div>
    <div className="grid grid-cols-2 gap-2">
      <Input name="address_zip" placeholder="ZIP / Postal code" />
