  </div>

  {/* Checkboxes */}
  <div className="space-y-3">
    <label className="flex items-start gap-3 cursor-pointer">
      <Checkbox name="backup_withholding" id="backup_withholding"
                defaultChecked={existing?.backup_withholding} />
