        <p className="text-sm font-medium">Subject to backup withholding</p>
        <p className="text-xs text-muted-foreground">
          Check this if the IRS has notified you that you are subject to backup withholding.
        </p>
      </div>
    </label>
    {showFatcaField && (
      <label className="flex items-start gap-3 cursor-pointer">
        <Checkbox name="fatca_exempt" id="fatca_exempt"
                  defaultChecked={existing?.fatca_exempt} />
        <div>
          <p className="text-sm font-medium">Exempt from FATCA reporting</p>
          <p className="text-xs text-muted-foreground">
            Applies to certain entity types. See IRS Form W-9 instructions for details.
          </p>
        </div>
      </label>
    )}
  </div>

  {/* Exempt payee code */}
  <div className="space-y-1.5">
    <Label htmlFor="exempt_payee_code">Exempt payee code (optional)</Label>
    <Input id="exempt_payee_code" name="exempt_payee_code" maxLength={4}
           placeholder="e.g., 5" className="max-w-xs" />
    <p className="text-xs text-muted-foreground">
      Only enter if exempt from backup withholding. See W-9 instructions.
    </p>
  </div>

  {/* Signer name */}
  <div className="space-y-1.5">
    <Label htmlFor="w9_signer_name">Signer name *</Label>
    <p className="text-xs text-muted-foreground">
